use crate::aap::caps::http_client;
use crate::aap::caps::types::{FeedDocument, FetchFailure};

struct Node;

const ALLOWED_HOSTS: [&str; 4] = [
    "simonwillison.net",
    "rss.arxiv.org",
    "bytecodealliance.org",
    "lobste.rs",
];

/// Extract the host of an http(s) URL, lowercased. Returns None if the URL
/// is not in a form we can confidently parse.
fn host_of(url: &str) -> Option<String> {
    let rest = url
        .strip_prefix("https://")
        .or_else(|| url.strip_prefix("http://"))?;
    let authority = rest
        .split(|c| c == '/' || c == '?' || c == '#')
        .next()
        .unwrap_or("");
    let hostport = authority.rsplit('@').next().unwrap_or("");
    let host = hostport.split(':').next().unwrap_or("");
    if host.is_empty() {
        None
    } else {
        Some(host.to_ascii_lowercase())
    }
}

impl Guest for Node {
    fn run(subscriptions: SubscriptionList) -> FeedBatch {
        let mut documents = Vec::new();
        let mut failures = Vec::new();

        for url in subscriptions.urls {
            // Out-of-allowlist requests trap at the boundary and would fail the
            // whole run, so record them as failures without making the call.
            let allowed = host_of(&url)
                .map(|h| ALLOWED_HOSTS.contains(&h.as_str()))
                .unwrap_or(false);
            if !allowed {
                failures.push(FetchFailure {
                    url,
                    error: "host not permitted".to_string(),
                });
                continue;
            }

            match http_client::fetch(&url) {
                Ok(body) => documents.push(FeedDocument { url, body }),
                Err(error) => failures.push(FetchFailure { url, error }),
            }
        }

        FeedBatch {
            documents,
            failures,
        }
    }
}

export!(Node);
